code=$(status -X POST $base_url/api/ping); check test "$code" = 405; check grep -qi '^Allow: GET' <(curl -sSI -X POST $base_url/api/ping)
code=$(status -X DELETE $base_url/api/legal); check test "$code" = 405
code=$(status $base_url/api/missing); check test "$code" = 404
code=$(status $base_url/api/oauth/linkedin/start); check test "$code" = 401
code=$(status -X POST -H 'Content-Type: application/json' --data '{' $base_url/api/auth/login); check test "$code" = 403
cookie=$(mktemp /tmp/social-post-test-cookie.XXXXXX); csrf_json=$(curl -sS -c "$cookie" $base_url/api/auth/csrf); csrf=$(printf '%s' "$csrf_json"|sed -n 's/.*"csrfToken":"\([a-f0-9]*\)".*/\1/p'); before=$(awk '$6=="SOCIALPOSTSESSID"{print $7}' "$cookie")
code=$(status -b "$cookie" -H 'Content-Type: application/json' -H "X-CSRF-Token: $csrf" --data '{' $base_url/api/auth/login); check test "$code" = 400
bad=$(printf '{"login":"%s","password":"wrong-password"}' "$INITIAL_ADMIN_USERNAME"); code=$(status -b "$cookie" -H 'Content-Type: application/json' -H "X-CSRF-Token: $csrf" --data "$bad" $base_url/api/auth/login); check test "$code" = 401
login=$(printf '{"login":"%s","password":"%s"}' "$INITIAL_ADMIN_USERNAME" "$INITIAL_ADMIN_PASSWORD"); response=$(curl -sS -b "$cookie" -c "$cookie" -H 'Content-Type: application/json' -H "X-CSRF-Token: $csrf" --data "$login" $base_url/api/auth/login); csrf=$(printf '%s' "$response"|sed -n 's/.*"csrfToken":"\([a-f0-9]*\)".*/\1/p'); after=$(awk '$6=="SOCIALPOSTSESSID"{print $7}' "$cookie"); check test -n "$csrf"; check test "$before" != "$after"
code=$(status $base_url/api/admin/providers); check test "$code" = 401
code=$(status -X PUT -H 'Content-Type: application/json' --data '{}' $base_url/api/admin/providers/linkedin); check test "$code" = 401
code=$(status $base_url/api/admin/email-settings);check test "$code" = 401
code=$(status -X PUT -H 'Content-Type: application/json' --data '{}' $base_url/api/admin/email-settings);check test "$code" = 401
email_settings='{"enabled":true,"host":"smtp.example.test","port":587,"encryption":"tls","user":"smtp-user","password":"smtp-secret-first","fromEmail":"sender@example.test","fromName":"Social Post","replyTo":"reply@example.test"}'
code=$(status -X PUT -b "$cookie" -H 'Content-Type: application/json' --data "$email_settings" $base_url/api/admin/email-settings);check test "$code" = 403
saved_email=$(curl -sS -X PUT -b "$cookie" -H "X-CSRF-Token: $csrf" -H 'Content-Type: application/json' --data "$email_settings" $base_url/api/admin/email-settings);check sh -c 'printf %s "$1"|grep -q '"'"'"hasPassword":true'"'"' && ! printf %s "$1"|grep -q '"'"'smtp-secret-first\|"password"'"'"'' sh "$saved_email"
loaded_email=$(curl -sS -b "$cookie" $base_url/api/admin/email-settings);check sh -c 'printf %s "$1"|grep -q '"'"'"host":"smtp.example.test"'"'"' && printf %s "$1"|grep -q '"'"'"replyTo":"reply@example.test"'"'"' && ! printf %s "$1"|grep -q '"'"'smtp-secret-first\|"password"'"'"'' sh "$loaded_email"
email_cipher_before=$("${compose[@]}" exec -T db sh -lc 'mariadb -u"$MARIADB_USER" -p"$MARIADB_PASSWORD" "$MARIADB_DATABASE" -Nse "SELECT CONCAT(smtp_password_encrypted LIKE \"spsec:%\",\":\",smtp_password_encrypted LIKE \"%smtp-secret-first%\",\":\",SHA2(smtp_password_encrypted,256)) FROM email_settings WHERE id=1"');check sh -c '[ "${1%%:*}" = 1 ] && [ "$(printf %s "$1"|cut -d: -f2)" = 0 ]' sh "$email_cipher_before";email_hash_before=${email_cipher_before##*:}
email_keep='{"enabled":true,"host":"smtp.example.test","port":465,"encryption":"ssl","user":"smtp-user","password":"","fromEmail":"sender@example.test","fromName":"Social Post Reload","replyTo":"reply@example.test"}';code=$(status -X PUT -b "$cookie" -H "X-CSRF-Token: $csrf" -H 'Content-Type: application/json' --data "$email_keep" $base_url/api/admin/email-settings);check test "$code" = 200;email_hash_after=$("${compose[@]}" exec -T db sh -lc 'mariadb -u"$MARIADB_USER" -p"$MARIADB_PASSWORD" "$MARIADB_DATABASE" -Nse "SELECT SHA2(smtp_password_encrypted,256) FROM email_settings WHERE id=1"');check test "$email_hash_before" = "$email_hash_after"
email_replace='{"enabled":true,"host":"smtp.example.test","port":25,"encryption":"none","user":"smtp-user","password":"smtp-secret-second","fromEmail":"sender@example.test","fromName":"Social Post","replyTo":""}';code=$(status -X PUT -b "$cookie" -H "X-CSRF-Token: $csrf" -H 'Content-Type: application/json' --data "$email_replace" $base_url/api/admin/email-settings);check test "$code" = 200;email_hash_replaced=$("${compose[@]}" exec -T db sh -lc 'mariadb -u"$MARIADB_USER" -p"$MARIADB_PASSWORD" "$MARIADB_DATABASE" -Nse "SELECT SHA2(smtp_password_encrypted,256) FROM email_settings WHERE id=1"');check test "$email_hash_before" != "$email_hash_replaced"
for invalid_email_payload in '{"enabled":false,"host":"","port":587,"encryption":"tls","user":"","password":"","fromEmail":"kaputt","fromName":"","replyTo":""}' '{"enabled":false,"host":"","port":587,"encryption":"tls","user":"","password":"","fromEmail":"","fromName":"","replyTo":"kaputt"}';do code=$(status -X PUT -b "$cookie" -H "X-CSRF-Token: $csrf" -H 'Content-Type: application/json' --data "$invalid_email_payload" $base_url/api/admin/email-settings);check test "$code" = 422;done
