blocks=$(curl -sS -b "$cookie" $base_url/api/admin/text-blocks);check sh -c 'printf %s "$1"|grep -q "standard_cta" && printf %s "$1"|grep -q "<img src=x onerror=alert(1)>"' sh "$blocks"
