code=$(status -X POST -b "$cookie" -H "X-CSRF-Token: $csrf" -H 'Content-Type: application/json' --data '{"title":"Syntax","key":"invalid_placeholder_syntax","category":"Allgemein","content":"Hallo {name}","isActive":true,"sortOrder":0}' $base_url/api/admin/text-blocks);check test "$code" = 422;check grep -q 'Ungültige Platzhaltersyntax' /tmp/social-post-test-body
