code=$(status -X POST -b "$cookie" -H "X-CSRF-Token: $csrf" -H 'Content-Type: application/json' --data '{"title":"Ungültig","key":"bad_boolean","category":"","content":"Text","isActive":1,"sortOrder":0}' $base_url/api/admin/text-blocks);check test "$code" = 422
