blocks=$(curl -sS -b "$cookie" $base_url/api/admin/text-blocks);check sh -c 'printf %s "$1"|grep -q "linkedin_cta" && printf %s "$1"|grep -q "\"isActive\":false" && printf %s "$1"|grep -q "\"sortOrder\":5"' sh "$blocks"
abschluss='{"title":"Abschluss","key":"abschluss","category":"Allgemein","content":"Viele Grüße","isActive":true,"sortOrder":1}';abschluss_created=$(curl -sS -X POST -b "$cookie" -H "X-CSRF-Token: $csrf" -H 'Content-Type: application/json' --data "$abschluss" $base_url/api/admin/text-blocks);abschluss_id=$(printf '%s' "$abschluss_created"|sed -n 's/.*"id":\([0-9]*\).*/\1/p');check test -n "$abschluss_id"
public_blocks=$(curl -sS $base_url/api/text-blocks);check sh -c 'printf %s "$1"|grep -q "\"key\":\"abschluss\"" && ! printf %s "$1"|grep -q "\"key\":\"linkedin_cta\""' sh "$public_blocks"
resolved=$(curl -sS -H 'Content-Type: application/json' --data '{"text":"Hallo! {{abschluss}}"}' $base_url/api/text-blocks/resolve);check sh -c 'printf %s "$1"|grep -q "\"text\":\"Hallo! Viele Grüße\""' sh "$resolved"
code=$(status -H 'Content-Type: application/json' --data '{"text":"Hallo {{unbekannt}}"}' $base_url/api/text-blocks/resolve);check test "$code" = 422;check grep -q 'Unbekannter Platzhalter' /tmp/social-post-test-body
haupttext='{"title":"Haupttext","key":"haupttext","category":"Allgemein","content":"Hallo. {{abschluss}}","isActive":true,"sortOrder":2}';haupttext_created=$(curl -sS -X POST -b "$cookie" -H "X-CSRF-Token: $csrf" -H 'Content-Type: application/json' --data "$haupttext" $base_url/api/admin/text-blocks);haupttext_id=$(printf '%s' "$haupttext_created"|sed -n 's/.*"id":\([0-9]*\).*/\1/p');check test -n "$haupttext_id"
code=$(status -X DELETE -b "$cookie" -H "X-CSRF-Token: $csrf" "$base_url/api/admin/text-blocks/$abschluss_id");check test "$code" = 409;check grep -q 'Haupttext' /tmp/social-post-test-body
abschluss_renamed='{"title":"Abschluss","key":"abschluss_neu","category":"Allgemein","content":"Viele Grüße","isActive":true,"sortOrder":1}';code=$(status -X PUT -b "$cookie" -H "X-CSRF-Token: $csrf" -H 'Content-Type: application/json' --data "$abschluss_renamed" "$base_url/api/admin/text-blocks/$abschluss_id");check test "$code" = 409;check grep -q 'Haupttext' /tmp/social-post-test-body
